import unittest

from hourglass.models import Span
from hourglass.parsing import parse_span
from hourglass.rounding import round_span, rounded_labels


class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest(self):
        self.assertEqual(
            round_span(parse_span("08:52-17:08"), 15), parse_span("09:00-17:15")
        )

    def test_halves_go_up(self):
        self.assertEqual(round_span(Span(67, 120), 15), Span(60, 120))
        self.assertEqual(round_span(Span(68, 130), 15), Span(75, 135))

    def test_end_of_day_stays(self):
        self.assertEqual(round_span(Span(0, 1439), 30), Span(0, 1440))

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(61, 64), 15)


class LabelTests(unittest.TestCase):
    def test_labels(self):
        spans = [parse_span("09:02-17:14"), parse_span("22:00-23:50")]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)", "22:00-23:45 (1h 45m)"]
        )

    def test_empty(self):
        self.assertEqual(rounded_labels([], 5), [])

    def test_bad_steps(self):
        for step in (0, -5, 7, 45, 61):
            with self.assertRaises(ValueError):
                rounded_labels([Span(0, 60)], step)

    def test_bad_step_with_no_spans(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    def test_valid_steps(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            self.assertEqual(len(rounded_labels([Span(0, 120)], step)), 1)
